from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
m.lesson(57,'Paggamit ng 3R at circular economy sa electrical products','Ihiwalay ang layunin ng 3R sa pahintulot ng paggamit at panatilihin ang safety sa resource circulation.',[
('Bawasan, gamitin muli, gawing resource','Reduce: bawasan ang paglikha ng waste; Reuse: ulitin ang gamit ng produkto; Recycle: muling gamitin bilang resource. Magkaiba ang packaging reduction, reusable collection box, at material separation. Hindi puwedeng alisin pati kailangang protective packaging.'),('Circulation mula sa design','Pinadadali ng circular economy ang repair/reuse upang tumagal ang pag-ikot ng produkto at materyal. Kasama ang pollution prevention, renewable energy, at natural environment. Kilalanin at inspeksiyunin ang reused items; huwag basta ibalik ang safety components.'),('Suriin din ang electrical conditions','DC: karaniwang isang direksiyon; AC: pana-panahong baligtad. May DC na nagbabago ang laki kahit iisa ang direksiyon. Huwag gawing compatible ang nakuhang supply o battery mula hugis/voltage lamang; suriin ang rating, polarity, kondisyon.')],['Tatlong gawain: bawasan ang paglikha, reuse, at resource recycling.','Pananaw na nagpapapaikot ng resources upang bawasan ang waste at environmental load.','Paulit-ulit na paggamit ng produkto.','Pagkakaiba ng positibo at negatibo at katulad nito.'],ACT+'Iuri sa 3R ang reusable shipping box, scrap reduction, at copper-wire separation. Isulat ang pag-check at storage ng recovered batteries.',['Huwag i-short ang battery terminals; kilalanin at itago ayon sa takda pati recovered items.'],'Ihiwalay ang layunin ng 3R sa pahintulot ng paggamit at panatilihin ang safety sa resource circulation.')
m.lesson(58,'Hiwalay na pagtiyak ng batas, technical requirements, at PSE','Ihiwalay ang kondisyon ng produkto, installation, at worker at tingnan ang petsa ng applicability.',[
('Layunin at target','Ang Electrical Appliances and Materials Safety Act ay sistema laban sa panganib ng saklaw na electrical products. Kaugnay ang PSE marking; iba ang hugis para sa specified at non-specified products. Itugma ang classification, notified supplier, at rating sa dokumento; hindi marka lamang ang approval sa lahat ng gamit.'),('Pagkakaiba sa installation requirements','Performance requirements ng installation ang ministerial ordinance sa technical standards; nagbibigay ng konkretong technical content ang interpretation upang matugunan ito. Hiwalay na tiyakin ang product selection, connection sa installation, at worker qualification/training.'),('Petsa ng dokumento','Huwag ilapat nang walang kondisyon sa lahat ng kasalukuyang produkto ang bilang ng saklaw na items o grounding exemptions ng textbook. Tiyakin ang marking, installation conditions, at qualifications sa pinakabagong official sources at responsable. Hindi dahilan ang earth-leakage breaker upang alisin ang grounding.')],['Electrical products/materials na saklaw ng legal classification.','Marking na kaugnay ng safety system ng saklaw na electrical products.','Order na itinatakda ng ministro ng kagawaran.','Technical requirements na dapat matugunan ng installation at iba pa.'],ACT+'Gumawa ng tatlong kolum: PSE target, installation compatibility, at worker duty. Isulat ang susuriin sa AC adapter na hindi alam ang specification.',['Huwag hulaan ang batas o grounding applicability upang mag-install o mag-alis.'],'Ihiwalay ang kondisyon ng produkto, installation, at worker at tingnan ang petsa ng applicability.')
m.lesson(59,'Pagkilala sa national, international, at industry standards','Itugma ang issuer, target, version, at pagkakaiba.',[
('Issuer at target','National standard ang JIS; industry ang JEM sa electrical manufacturing, JEITA sa electronics/information technology, JSIA sa distribution/control systems. Iba ang issuer/target ayon sa pangalan. Ihiwalay din ang basic terms/units, test methods, at product standards.'),('International at overseas requirements','IEC ang gumagawa ng electrical international standards; ISO sa malawak na mga field. Iba ang posisyon ng NEC, VDE, IEEE ayon sa rehiyon, organisasyon, at target. Sa export, tiyakin ang country at contractual requirements.'),('Huwag ipagpalagay ang pagkakatumbas','Kahit may corresponding JIS/IEC, huwag parehong-pareho nang walang version/difference check. Sa lumang/bagong drawing symbols, tingnan ang legend at applicable standard. Itala ang number, year/version, at application bago iugnay sa assembly.')],['Organisasyon ng international standardization sa electrical field.','Standard na itinakda ng industry association.','Version ng publication o revision date ng standard.','Pagtutugma ng mga requirements.'],ACT+'Bago domestic part sa export panel, ayusin ang destination, standard number, version, differences, at approved drawing checks.',['Huwag maggarantiya ng protection/rating compatibility mula pangalan lamang ng overseas standard.'],'Itugma ang issuer, target, version, at pagkakaiba.')
m.lesson(60,'Uri ng drawing, papel, at third-angle projection','Itugma ang identification at projection direction upang basahin ang hugis.',[
('Aling drawing ang gagamitin','Iuri ayon sa layunin na production/planning/approval, expression na outline/exploded/connection, at content na part/assembly/layout. Listahan ng parts ang bill of materials. Suriin ang title block, drawing number, revision, at sheets; huwag ihalo ang ibang produkto.'),('Papel at border','A4 ay210×297mm, A3 ay297×420mm; sa A-series, kalahati ng mas malaking sheet ang kasunod. Tingnan ang border, title block, at margins at basahin ang nakasulat na dimensions kahit scaled print. Huwag ipagkamali ang paper size sa product size.'),('View direction at posisyon','Sa third-angle, top view sa taas ng front, right view sa kanan, left sa kaliwa. Itugma ang visible/hidden shapes mula bawat direksiyon at tingnan ang projection symbol. Hindi lahat ng bansa/drawing ay third-angle.')],['Orthographic method na inilalagay ang view sa panig ng direksiyong tiningnan.','Kolum ng drawing number, pangalan, at iba pa.','Listahan ng parts sa assembly.','Pangunahing projection na kumakatawan sa hugis at function.'],ACT+'Iguhit ang ayos ng front/top/right views ng maliit na stepped part. Gumawa ng query kung hindi alam ang drawing number, revision, o projection.',['Huwag hulaan ang hole/cut location sa hindi malinaw na drawing.'],'Itugma ang identification at projection direction upang basahin ang hugis.')
m.lesson(61,'Requirements ng dimension, roughness, at fit','Basahin bilang magkakaibang requirement ang dimension, roughness, at fit.',[
('Kahulugan ng linya at sukat','Iba ang outline, hidden, center, dimension, cutting plane, at hatching. Final requirement ang dimensions; ihiwalay ang radius R, diameterφ, arc, chord, at angle. Huwag humula ng length/angle sa hitsura.'),('Roughness at machining','Ra ang arithmetic average roughness; sa parehong kondisyon, mas maliit ay mas makinis. Ihiwalay ang roughness μm at dimension mm at itugma pati process note. Iba ang symbols ayon sa standard/version; huwag ituring na current ang luma.'),('Shaft at hole nang magkasama','Clearance, interference, at transition fits ay kumbinasyon ng allowable dimensions ng shaft/hole. Hindi pareho ang aktuwal na relation kahit nominal. Huwag kusang press-fit o painitin; tingnan ang tolerances at aprubadong assembly method.')],['Ra na index ng laki ng surface irregularities.','Kombinasyon ng allowable size ranges ng shaft at hole.','Fit na maaaring may clearance o interference ayon sa allowable sizes.','Parallel diagonal lines sa section at iba pa.'],ACT+'Kalkulahin ang clearance ng hole20.02mm at shaft19.98mm at bakit hindi sapat ang nominal20mm. Ihiwalay ang Ra3.2μm at3.2mm.',['Huwag piliting i-assemble gamit ang force/heat kung hindi alam ang tolerance.'],'Basahin bilang magkakaibang requirement ang dimension, roughness, at fit.')
m.lesson(62,'Electrical symbols at pagbasa ng ladder','Itugma ang terminal, device identification, at state; ihiwalay ang logic sa physical wiring.',[
('Kilalanin mula sa symbol','Itugma ang resistor, variable resistor, capacitor, coil, diode, LED, transistor, fuse, meter, contact. Magkaiba ang light arrows ng emitting LED at receiving photodiode. Tingnan din ang terminal roles ng A/K at B/C/E.'),('Iugnay ang magkakalayong contacts','Sa developed diagram, magkahiwalay ang coil at contacts ng parehong relay. Iugnay sa equipment symbol/reference, hindi dahil malapit. Ihiwalay normal/operated state: a-contact closes, b-contact opens sa actuation.'),('Hindi physical wiring ang ladder','Sa batayang PLC ladder, pag-aralan ang top-to-bottom at left-to-right evaluation. Ihiwalay ang input conditions, internal relay, output; huwag ipaghalo ang a/b instructions at physical switch wiring. Tiyakin ang tunay na order at special instructions sa model specification.')],['Diagram na inilatag upang madaling basahin ang operating relation.','Diagram/programa na nagsusulat ng control conditions sa ladder form.','Elementong nagpapanatili ng condition state sa controller.','Impormasyong nagtuturo sa related symbol location.'],ACT+'Isulat ang kondisyon ng inputP, internal relayM, lampY at paraan ng paghahanap ng contact na kapareho ng coil symbol. Ipaliwanag ang pagkakaiba ng LED at receiver.',['Huwag basta baguhin ang safety circuit mula pag-aaral lamang ng symbols.'],'Itugma ang terminal, device identification, at state; ihiwalay ang logic sa physical wiring.')
m.lesson(63,'Conductive/magnetic materials at thermal classes','Hiwalay na itugma ang electrical, magnetic, at thermal properties.',[
('Pagkakaiba ng wire materials','Soft copper wire ay annealed upang bawasan ang work-hardening; iba ang strength, conductivity, mass sa hard copper/aluminum. Kahit parehong length/section, iba ang resistance sa materyal. Iba ang hindi naaakit ng magnet at hindi conductive.'),('Magnetic retention o pagbabago','Nababawasan ng laminated thin electrical steel ang losses mula flux change. Sa permanent magnets, itugma ang remanence/coercivity sa gamit. Huwag ipalit ang lahat ng magnetic materials sa parehong core o permanent magnet.'),('Thermal conditions ng insulation','Mga halimbawa: Y90,A105,E120,B130,F155,H180,R220°C. Para ito sa takdang material/insulation-system conditions, hindi ambient temperature ng lahat. Hindi inorganic ang natural rubber; mica/ceramic ang examples. Huwag ding iuri na inorganic ang paper materials.')],['Controlled heating na nagpapalambot ng materyal.','Katangiang kaugnay ng field upang alisin ang natitirang magnetization.','Low-loss steel sheet para sa core at iba pa.','Thermal classification ng insulation sa takdang kondisyon.'],ACT+'Gumawa ng table ng copper/aluminum sa parehong sukat, core/permanent magnet, at thermal class/ambient temperature.',['Huwag thermal class lamang ang batayan ng temperature o interchangeability.'],'Hiwalay na itugma ang electrical, magnetic, at thermal properties.')
m.lesson(64,'Pagkilala sa wire types at connection parts','Basahin ang marking at tunay na specifications at panatilihin ang connection/fastening combination.',[
('Marking at specification','IV,KIV,KV ang identifiers ng wires na magkakaiba ang gamit/structure. Tingnan ang voltage class, temperature, solid/stranded, conductor area, insulation, at destination. Huwag gawing mandatory sa lahat ang textbook color/size examples.'),('Tool ayon sa layunin','Pliers,long-nose,cutters,strippers ay magkakaiba sa holding,bending,cutting,stripping. Itugma ang crimp terminal sa conductor at screw at tingnan ang crimp die profile. Ihiwalay ang pag-alis ng outer sheath at conductor insulation.'),('Panatilihin ang fastening configuration','May takdang gamit/kombinasyon ang nut,flat washer,spring washer,washer-assembled screw. Trapezoidal thread ang para sa feed mechanisms at iba pa. Tingnan ang drawing kapag iba ang material/target;huwag kusang alisin ang orientation o quantity ng parts.')],['Outer covering ng buong cable.','Hugis ng tool area na kumikilos sa materyal sa crimping at iba pa.','Trapezoidal-section thread para sa feed at iba pa.','Identifier ng vinyl-insulated wire para sa electrical equipment.'],ACT+'Gumawa ng matching checklist ng wire,terminal,tool,mounting screw. Ipaliwanag ang mm/mm² at sheath/core insulation.',['Huwag mag-test energize ng hindi alam na wire/terminal compatibility.'],'Basahin ang marking at tunay na specifications at panatilihin ang connection/fastening combination.')
